      "Galerie image 5: https://fabo.com.tr/wp-content/uploads/2021/09/tertiary-impact-crusher-tertiary-crusher-2.jpg",
      "Galerie image 6: https://fabo.com.tr/wp-content/uploads/2021/09/crushing-screening-plant-4.jpg",
      "Galerie image 7: https://fabo.com.tr/wp-content/uploads/2021/09/vibrating-screen-2.jpg",
      "Galerie image 8: https://fabo.com.tr/wp-content/uploads/2021/09/stock-belt.jpg",
      "Galerie image 9: https://fabo.com.tr/wp-content/uploads/2021/09/screening-plant-1.jpg",
